-- TIU 6: run AFTER update-03-tiu5-session.sql. Preserves existing answers.
begin;
alter table public.test_attempts drop constraint if exists test_attempts_test_code_check;
alter table public.test_attempts add constraint test_attempts_test_code_check check(test_code in ('test1','test2','tiu5','tiu6'));
alter table public.test_attempts add column if not exists session_deadline_at timestamptz;
alter table public.test_attempts add column if not exists answer_revision integer not null default 0;
alter table public.test_settings drop constraint if exists test_settings_test_code_check;
alter table public.test_settings add constraint test_settings_test_code_check check(test_code in ('test1','test2','tiu5','tiu6'));
alter table public.test_settings add column if not exists session_duration_seconds integer check(session_duration_seconds between 60 and 86400);
alter table public.question_bank drop constraint if exists question_bank_test_code_check;
alter table public.question_bank add constraint question_bank_test_code_check check(test_code in ('test1','test2','tiu5','tiu6'));
alter table public.question_bank drop constraint if exists question_bank_question_type_check;
alter table public.question_bank add constraint question_bank_question_type_check check(question_type in ('paired_choice','most_least','image_choice','binary_svg'));
alter table public.question_bank add column if not exists visual_data jsonb;
insert into public.test_settings(test_code,display_name,randomize_questions,randomize_options,allow_back,active,sort_order)
select 'tiu6','TIU 6 - Jaring-jaring Bangun',false,false,true,true,coalesce(max(sort_order),0)+1 from public.test_settings
on conflict(test_code) do nothing;
